// Supabase Edge Function "smtp-mail"
// -----------------------------------------------------------------------------
// Sends one email through Gmail / Google Workspace using an App password.
// It exists because the database cannot speak SMTP. Only the database calls it (through pg_net),
// and every call must carry the secret relay key below, so it cannot be used by anyone else.
//
// You do not edit this file by hand: Admin > Email settings shows a ready-to-paste copy with the key filled in.
// Install it: Supabase dashboard > Edge Functions > Deploy a new function > Via Editor, name it  smtp-mail,
// paste this code, Deploy, then open its Details tab and switch OFF "Verify JWT".

const RELAY_KEY = '__RELAY_KEY__'
const SMTP_HOST = 'smtp.gmail.com'
const SMTP_PORT = 465 // encrypted from the first byte; Edge Functions cannot use ports 25 or 587

export interface Conn {
  read(p: Uint8Array): Promise<number | null>
  write(p: Uint8Array): Promise<number>
  close(): void
}

export interface MailIn {
  user: string
  pass: string
  fromName: string
  to: string[]
  subject: string
  html: string
  text: string
  replyTo?: string
}

export class SmtpError extends Error {}

const EMAIL_RE = /^[^\s@<>",;]+@[^\s@<>",;]+\.[^\s@<>",;]+$/
const enc = new TextEncoder()
const dec = new TextDecoder()
const PLAIN_ASCII = /^[\x20-\x7e]*$/

const oneLine = (s: string) => s.replace(/[\r\n]+/g, ' ').trim()

function toBase64(bytes: Uint8Array): string {
  let bin = ''
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
  return btoa(bin)
}

const wrap76 = (b64: string) => (b64.match(/.{1,76}/g) ?? []).join('\r\n')

/** Header text that is not plain ASCII is sent as RFC 2047 encoded words (so names and subjects in any language survive). */
export function encodeWord(s: string): string {
  if (PLAIN_ASCII.test(s)) return s
  const words: string[] = []
  let cur = ''
  let bytes = 0
  for (const ch of s) {
    const n = enc.encode(ch).length
    if (bytes + n > 45) { words.push(cur); cur = ''; bytes = 0 }
    cur += ch
    bytes += n
  }
  if (cur) words.push(cur)
  return words.map((w) => `=?UTF-8?B?${toBase64(enc.encode(w))}?=`).join('\r\n ')
}

/** Lines that start with a dot are doubled, as SMTP requires, so the message cannot end early. */
export const dotStuff = (s: string) => s.replace(/\r?\n/g, '\r\n').replace(/^\./gm, '..')

export function buildMessage(m: MailIn, boundary: string, date: Date, id: string): string {
  const name = oneLine(m.fromName).replace(/["<>\\]/g, '')
  const fromName = name === '' ? '' : PLAIN_ASCII.test(name) ? `"${name}" ` : `${encodeWord(name)} `
  const headers = [
    `From: ${fromName}<${m.user}>`,
    `To: ${m.to.join(', ')}`,
    ...(m.replyTo ? [`Reply-To: ${m.replyTo}`] : []),
    `Subject: ${encodeWord(oneLine(m.subject))}`,
    `Date: ${date.toUTCString()}`,
    `Message-ID: <${id}@${m.user.split('@')[1]}>`,
    'MIME-Version: 1.0',
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
  ]
  const part = (type: string, body: string) =>
    [`--${boundary}`, `Content-Type: ${type}; charset=UTF-8`, 'Content-Transfer-Encoding: base64', '', wrap76(toBase64(enc.encode(body)))].join('\r\n')
  return `${headers.join('\r\n')}\r\n\r\n${part('text/plain', m.text)}\r\n${part('text/html', m.html)}\r\n--${boundary}--\r\n`
}

async function writeAll(conn: Conn, bytes: Uint8Array): Promise<void> {
  let off = 0
  while (off < bytes.length) off += await conn.write(bytes.subarray(off))
}

class Session {
  private buf = ''
  private readonly chunk = new Uint8Array(4096)
  private readonly conn: Conn
  constructor(conn: Conn) { this.conn = conn }

  private async line(): Promise<string> {
    for (;;) {
      const i = this.buf.indexOf('\n')
      if (i >= 0) {
        const l = this.buf.slice(0, i).replace(/\r$/, '')
        this.buf = this.buf.slice(i + 1)
        return l
      }
      const n = await this.conn.read(this.chunk)
      if (n === null) throw new SmtpError('The mail server closed the connection')
      this.buf += dec.decode(this.chunk.subarray(0, n), { stream: true })
    }
  }

  async reply(): Promise<{ code: number; text: string }> {
    const lines: string[] = []
    for (;;) {
      const l = await this.line()
      lines.push(l)
      if (/^\d{3}(?: |$)/.test(l)) return { code: parseInt(l.slice(0, 3), 10), text: lines.map((x) => x.slice(4)).join(' ') }
      if (!/^\d{3}-/.test(l)) throw new SmtpError(`Unexpected reply from the mail server: ${l.slice(0, 100)}`)
    }
  }

  send(line: string): Promise<void> { return writeAll(this.conn, enc.encode(`${line}\r\n`)) }

  async cmd(line: string, ok: number[], label: string): Promise<void> {
    await this.send(line)
    const r = await this.reply()
    if (!ok.includes(r.code)) throw new SmtpError(`${label} failed: ${r.code} ${r.text}`.slice(0, 300))
  }
}

/** One complete SMTP conversation on an already connected, encrypted connection. */
export async function sendSmtp(conn: Conn, m: MailIn, boundary: string = crypto.randomUUID(), date: Date = new Date(), id: string = crypto.randomUUID()): Promise<void> {
  const s = new Session(conn)
  const hello = await s.reply()
  if (hello.code !== 220) throw new SmtpError(`The mail server did not accept the connection: ${hello.code} ${hello.text}`.slice(0, 300))
  await s.cmd('EHLO ultraplast-mail', [250], 'EHLO')
  // the password is only ever inside this one line and is never repeated in an error message
  await s.cmd(`AUTH PLAIN ${toBase64(enc.encode(`\0${m.user}\0${m.pass}`))}`, [235], 'Sign-in to Gmail')
  await s.cmd(`MAIL FROM:<${m.user}>`, [250], 'MAIL FROM')
  for (const to of m.to) {
    await s.send(`RCPT TO:<${to}>`)
    const r = await s.reply()
    if (r.code !== 250 && r.code !== 251) throw new SmtpError(`The address ${to} was refused: ${r.code} ${r.text}`.slice(0, 300))
  }
  await s.cmd('DATA', [354], 'DATA')
  await writeAll(conn, enc.encode(`${dotStuff(buildMessage(m, boundary, date, id))}.\r\n`))
  const done = await s.reply()
  if (done.code !== 250) throw new SmtpError(`The message was not accepted: ${done.code} ${done.text}`.slice(0, 300))
  try { await s.send('QUIT') } catch { /* the message is already accepted */ }
}

export function parseRequest(body: unknown): { ok: true; mail: MailIn } | { ok: false; error: string } {
  if (typeof body !== 'object' || body === null) return { ok: false, error: 'The request body must be JSON' }
  const b = body as Record<string, unknown>
  const str = (k: string) => (typeof b[k] === 'string' ? (b[k] as string) : '')
  const user = str('smtp_user').trim()
  const pass = str('smtp_pass')
  const subject = oneLine(str('subject'))
  const html = str('html')
  const text = str('text')
  const replyTo = str('reply_to').trim()
  const to = Array.isArray(b.to) ? b.to.map((x) => (typeof x === 'string' ? x.trim() : '')) : []
  if (!EMAIL_RE.test(user) || user.length > 254) return { ok: false, error: 'The Gmail address is not valid' }
  if (!/^\S{8,128}$/.test(pass)) return { ok: false, error: 'The app password is missing or not valid' }
  if (to.length < 1 || to.length > 10 || to.some((x) => !EMAIL_RE.test(x) || x.length > 254)) return { ok: false, error: 'Recipients must be 1 to 10 valid email addresses' }
  if (subject.length < 1 || subject.length > 300) return { ok: false, error: 'The subject must be 1 to 300 characters' }
  if (html.length < 1 || html.length > 600000 || text.length > 200000) return { ok: false, error: 'The message is empty or too large' }
  if (replyTo !== '' && (!EMAIL_RE.test(replyTo) || replyTo.length > 254)) return { ok: false, error: 'The reply-to address is not valid' }
  return { ok: true, mail: { user, pass, fromName: str('from_name').slice(0, 80), to, subject, html, text, ...(replyTo ? { replyTo } : {}) } }
}

const json = (status: number, body: Record<string, unknown>) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })

function safeEqual(a: string, b: string): boolean {
  let diff = a.length ^ b.length
  const n = Math.max(a.length, b.length)
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0)
  return diff === 0
}

async function withTimeout<T>(p: Promise<T>, ms: number, message: string): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new SmtpError(message)), ms) })
  try { return await Promise.race([p, timeout]) } finally { clearTimeout(timer) }
}

export async function handle(req: Request, relayKey: string, connect: () => Promise<Conn>): Promise<Response> {
  if (req.method !== 'POST') return json(405, { error: 'Use POST' })
  if (relayKey === '' || relayKey.startsWith('__')) return json(500, { error: 'This function is not set up yet: copy it again from Admin, Email settings' })
  if (!safeEqual(req.headers.get('x-relay-key') ?? '', relayKey)) return json(401, { error: 'Wrong relay key: copy the function again from Admin, Email settings' })
  let body: unknown
  try { body = await req.json() } catch { return json(400, { error: 'The request body must be JSON' }) }
  const parsed = parseRequest(body)
  if (!parsed.ok) return json(400, { error: parsed.error })
  let conn: Conn | undefined
  try {
    conn = await withTimeout(connect(), 10000, `Could not connect to ${SMTP_HOST}`)
    await withTimeout(sendSmtp(conn, parsed.mail), 25000, 'The mail server took too long to answer')
    return json(200, { ok: true })
  } catch (e) {
    return json(502, { error: e instanceof Error ? e.message.slice(0, 300) : 'Sending failed' })
  } finally {
    try { conn?.close() } catch { /* already closed */ }
  }
}

interface DenoLike {
  serve(handler: (req: Request) => Response | Promise<Response>): unknown
  connectTls(options: { hostname: string; port: number }): Promise<Conn>
}
const deno = (globalThis as unknown as { Deno?: DenoLike }).Deno
if (deno) deno.serve((req) => handle(req, RELAY_KEY, () => deno.connectTls({ hostname: SMTP_HOST, port: SMTP_PORT })))
